@startuml

class Customer {
  + Name : string
  + Surname : string
  + Email : string
  + Telephone : string
  + HomeAddress : string
}

class Order {
  + TotalCost : double
  + EstimatedDeliveryTime : time
  + Status : string
}

class Dish {
  + Name : string
  + PreparationTime : int
}

class Payment {
  + Success : boolean
}

Customer "1" -- "*" Order : places
Order "1" *-- "1..*" Dish : contains
Order "1" -- "0..1" Payment : processed by

@enduml

